// /frontend-react/src/components/MedicineReminder.js

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import HeaderBar from './HeaderBar';

// --- LOCAL MOCK DATA ---
const mockMedicineData = {
    medicineName: "Blood Pressure Pill",
    dosage: "5mg",
    frequency: "Once Daily (Morning)",
    lastTaken: "2025-12-05 08:00 AM",
    pillsRemaining: 10,
    isRefillLow: true, 
    refillDate: "2025-12-12",
    courier: {
        name: "Alex C.",
        deliveryVehicle: "Bike Courier",
        eta: "3 hours",
    }
};

function MedicineReminder({ isEasyMode, goToPage, onMenuClick }) { 
    // HOOKS and LOCAL STATE
    const { t } = useTranslation();
    const [isDeliveryConfirmed, setIsDeliveryConfirmed] = useState(false);
    const [isDeliveryNeeded, setIsDeliveryNeeded] = useState(null); 
    const [successToastMessage, setSuccessToastMessage] = useState(''); 
    const [showSuccessToast, setShowSuccessToast] = useState(false); 

    const medicine = mockMedicineData;

    // --- Daily Reminder Logic ---
    const handleTaken = () => {
        console.log("Medicine Taken confirmed! Displaying centered toast notification.");
        
        // Setting the mock message from the image
        const message = "Confirmed! Next pill due tomorrow morning."; // NOTE: Using hardcoded text from image for visual parity
        
        setSuccessToastMessage(message);
        setShowSuccessToast(true);
        
        // Hide the toast after 3 seconds
        setTimeout(() => {
            setShowSuccessToast(false);
            setSuccessToastMessage('');
        }, 3000);
    };

    // --- Refill Logic Handlers ---
    const handleRefillDecision = (needed) => {
        setIsDeliveryNeeded(needed);
        if (needed) {
            setTimeout(() => {
                setIsDeliveryConfirmed(true);
                console.log("Delivery booked, showing courier status.");
            }, 500);
        } else {
            console.log("Delivery declined.");
        }
    };

    // 🛑 START OF STYLE DECLARATIONS 🛑
    
    const PHONE_MAX_WIDTH = '450px';

    const ctaText = t('medicine.reminder_cta');
    const baseFontSize = isEasyMode ? 36 : 24;
    let buttonFontSize = baseFontSize;

    // Adjust font size for long translated CTA text
    if (ctaText && ctaText.length > 18) {
        buttonFontSize = isEasyMode ? 28 : 20; 
    } else if (ctaText && ctaText.length > 12) {
          buttonFontSize = isEasyMode ? 32 : 22;
    }
    
    // Style for the main daily reminder button
    const descriptiveReminderButtonStyle = {
        padding: '20px',
        backgroundColor: '#4CAF50',
        color: 'white',
        fontSize: isEasyMode ? '24px' : '16px', 
        fontWeight: '900',
        borderRadius: '15px',
        width: '90%',
        maxWidth: '350px', 
        display: 'flex', 
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        border: 'none',
        cursor: 'pointer',
        boxShadow: '0 8px 20px rgba(0, 70, 0, 0.4)',
        animation: 'pulse-take 1.5s infinite',
        margin: '25px auto 40px auto', 
    };

    const actionButtonStyle = {
        padding: '15px 30px',
        fontSize: isEasyMode ? '28px' : '18px',
        borderRadius: '8px',
        border: '2px solid #ccc',
        fontWeight: 'bold',
        cursor: 'pointer',
        margin: '15px 10px',
    };

    // Style for the new centered toast notification
    const toastStyle = {
        position: 'fixed',
        // Set Y-position higher up the screen
        top: '15%', // FIX: Moved up closer to the header bar
        left: '50%',
        opacity: showSuccessToast ? 1 : 0, 
        transform: showSuccessToast ? 'translate(-50%, -50%) scale(1)' : 'translate(-50%, -50%) scale(0.8)',
        
        backgroundColor: '#616161', // Neutral Gray
        color: '#FFFFFF',
        // FIX: Using a wider horizontal padding (25px) and shorter vertical padding (15px) for the rectangular shape
        padding: '15px 25px', 
        borderRadius: '12px', 
        zIndex: 1000,
        boxShadow: '0 8px 20px rgba(0,0,0,0.5)', 
        fontSize: isEasyMode ? '22px' : '16px', // Smaller font for wider box
        fontWeight: 'bold', 
        transition: 'transform 0.4s ease-out, opacity 0.4s ease-out', 
        pointerEvents: showSuccessToast ? 'auto' : 'none',
        
        // FIX: Ensure it is a wide rectangle and does not exceed container
        width: 'auto', 
        maxWidth: '90%', // Use almost full width of the container
        boxSizing: 'border-box',
        textAlign: 'center',
        overflowWrap: 'break-word',
        lineHeight: '1.4',
    };
    
    // Shared Card Style for Refill/Delivery Sections
    const cardStyle = {
        padding: '25px', 
        borderRadius: '20px', 
        marginBottom: '30px',
        boxShadow: '0 5px 15px rgba(0,0,0,0.1)',
        margin: '0 auto 30px auto', // Center the card
        maxWidth: '400px'
    };
    
    // 🛑 END OF STYLE DECLARATIONS 🛑

    return (
        <div style={{ padding: '0 20px 20px 20px', textAlign: 'center', maxWidth: PHONE_MAX_WIDTH, margin: '0 auto' }}>
            
            {/* IN-APP TOAST NOTIFICATION (Centered on screen) */}
            <div style={toastStyle}>
                ✅ {successToastMessage}
            </div>
            
            <HeaderBar 
                title={t('header.title_medicine')} 
                onBackClick={() => goToPage('medical-dashboard')} 
                onMenuClick={onMenuClick} 
                isEasyMode={isEasyMode} 
            />

            <h2 style={{ fontSize: isEasyMode ? '40px' : '30px', margin: '70px 0 10px 0', color: '#1A73E8' }}>
                {t('medicine.reminder_daily')}
            </h2>

            {/* 1. Daily Reminder Action */}
            <button 
                onClick={handleTaken}
                style={descriptiveReminderButtonStyle} 
            >
                <span style={{ fontSize: isEasyMode ? '60px' : '40px', display: 'block', marginBottom: '10px' }}>
                    💊
                </span>
                {/* Medicine name and dosage inside the button */}
                <span style={{ 
                    fontSize: isEasyMode ? '28px' : '20px', 
                    fontWeight: 'bold', 
                    marginBottom: '5px' 
                }}>
                    {medicine.medicineName} ({medicine.dosage})
                </span>
                {/* CTA text */}
                <span style={{ 
                    fontSize: buttonFontSize, 
                    fontWeight: '900',
                    textDecoration: 'underline'
                }}>
                    {t('medicine.reminder_cta')}
                </span>
            </button>

            {/* Remove the redundant text below the button */}
            <div style={{ marginBottom: '40px' }} /> 

            {/* 2. Refill Warning Section */}
            {medicine.isRefillLow && !isDeliveryConfirmed && (
                <div style={{
                    ...cardStyle, // Use shared card style
                    border: '4px solid darkred', 
                    backgroundColor: '#FFDDDD', 
                    animation: 'alert-pulse 1s infinite'
                }}>
                    <h3 style={{ fontSize: isEasyMode ? '36px' : '24px', margin: '0 0 20px 0', color: 'darkred' }}>
                        {t('medicine.low_alert')} ⚠️
                    </h3>
                    <p style={{ fontSize: isEasyMode ? '24px' : '18px', margin: '15px 0' }}>
                        {t('medicine.running_out_prefix')} **{medicine.pillsRemaining} {t('medicine.days_label')}**.
                    </p>

                    {/* Refill Decision Prompt */}
                    {isDeliveryNeeded === null ? (
                        <div>
                            <p style={{ fontSize: isEasyMode ? '28px' : '20px', fontWeight: 'bold', margin: '20px 0 10px 0' }}>
                                {t('medicine.delivery_question')}
                            </p>
                            <button 
                                onClick={() => handleRefillDecision(true)} 
                                style={{...actionButtonStyle, backgroundColor: 'blue', color: 'white'}}
                            >
                                {t('medicine.delivery_yes_button')} 🚚
                            </button>
                            <button 
                                onClick={() => handleRefillDecision(false)} 
                                style={{...actionButtonStyle, backgroundColor: '#ccc'}}
                            >
                                {t('medicine.delivery_no_button')} 🚶
                            </button>
                        </div>
                    ) : (
                        // Confirmation message for No Delivery
                        !isDeliveryNeeded && (
                            <p style={{ fontSize: isEasyMode ? '24px' : '16px', color: 'darkred', fontWeight: 'bold' }}>
                                {t('medicine.pickup_reminder_conf')}
                            </p>
                        )
                    )}
                </div>
            )}

            {/* 3. Delivery Confirmation Status */}
            {isDeliveryConfirmed && (
                <div style={{
                    ...cardStyle, // Use shared card style
                    border: '4px solid green',
                    backgroundColor: '#E6FBE6',
                }}>
                    <h3 style={{ fontSize: isEasyMode ? '36px' : '24px', margin: '0 0 15px 0', color: 'green' }}>
                        {t('medicine.delivery_confirmed_header')}
                    </h3>
                    <p style={{ fontSize: isEasyMode ? '24px' : '18px', margin: '5px 0' }}>
                        {t('medicine.courier_label')}: **{medicine.courier.name}**
                    </p>
                    <p style={{ fontSize: isEasyMode ? '24px' : '18px', margin: '5px 0' }}>
                        {t('medicine.eta_label')}: **{medicine.courier.eta}**
                    </p>
                    <span role="img" aria-label={t('medicine.package_aria_label')} style={{fontSize: isEasyMode ? '50px' : '30px'}}>📦</span>
                </div>
            )}

            {/* CSS Keyframes (remain the same) */}
            <style jsx>{`
                @keyframes pulse-take {
                    0% { box-shadow: 0 0 10px green; }
                    50% { box-shadow: 0 0 20px limegreen; }
                    100% { box-shadow: 0 0 10px green; }
                }
                @keyframes alert-pulse {
                    0% { transform: scale(1); }
                    50% { transform: scale(1.01); }
                    100% { transform: scale(1); }
                }
            `}</style>
        </div>
    );
}

export default MedicineReminder;
